window.LAB_DATA = {"generatedFrom":"reader-web@11a26c8","generatedAt":"2026-10-29T14:47:17.290Z","novels":[{"id":"kyudo-senpai","title":"(WN) รุ่นพี่สาวสวยจากชมรมยิงธนู ผมนอนในห้องของผมโดยที่ท้องของเธอเปิดโล่ง","originalTitle":"弓道部の美人な先輩が、俺の部屋でお腹出して寝てる","author":"四条彼方 (Shijou Kanata)","artist":"ぶし (Bushi)","synopsis":"อาเมโมโตะ โทยะ นักเรียนมัธยมปลายธรรมดาผู้รักความสงบ คืนหนึ่งระหว่างออกมาซื้อของที่ร้านสะดวกซื้อกลางดึก เขาได้บังเอิญพบกับ วาตานูกิ ริโนะ ประธานชมรมยิงธนูสาวสวยระดับท็อปของโรงเรียน ผู้เหนื่อยล้าแทบหมดแรงกำลังแอบครอบครัวกว้านซื้อเครื่องดื่มชูกำลัง... จากความช่วยเหลือธรรมดาค่อยๆ พัฒนาสู่ความไว้วางใจ จนกลายเป็นว่ารุ่นพี่สาวสวยเริ่มแวะเวียนมานอนหลับสบายใจในห้องของเขาอย่างเปิดเผย (จนกระทั่งนอนเปิดพุงหลับปุ๋ยอย่างไร้การระแวง!) ก่อเกิดเป็นเรื่องราวความรักโรแมนติกคอมเมดี้ในชีวิตประจำวันอันแสนอบอุ่นและชวนใจฟู","tags":["Romance","Comedy","School Life","Slice of Life","Wholesome & Fluffy"],"totalOriginalChapters":73,"cover":"/web-v2/assets/novels/kyudo-senpai/cover.webp","banner":"/web-v2/assets/novels/kyudo-senpai/banner.webp","chapters":[{"id":"ch-00","number":0,"title":"รูปภาพประกอบนิยาย & ภาพสีเปิดเล่ม","blocks":[]},{"id":"ch-01","number":1,"title":"อีเวนต์หายากกลางดึก ①","blocks":[{"id":"b-1","type":"narration","text":"พอเปลี่ยนเวลาเดินทางไปโรงเรียน ผมก็พลอยได้เห็นอะไรแปลกตาขึ้นมา"},{"id":"b-2","type":"narration","text":"นักเรียนหญิงสูงโปร่งคนหนึ่งยืนรอสัญญาณไฟจราจรอยู่บนทางไปโรงเรียน——มองแค่นั้นก็ยังถือเป็นภาพชินตาที่เห็นได้ทั่วไป แต่สิ่งที่สะดุดตาเป็นพิเศษ น่าจะเป็นท่วงท่ายืนของเธอมากกว่า"},{"id":"b-3","type":"narration","text":"แค่ยืนรอสัญญาณไฟแท้ๆ แต่เธอกลับยืดหลังตรงเป๊ะราวกับกำลังรอรับใบประกาศเกียรติคุณอยู่ยังไงอย่างนั้น"},{"id":"b-4","type":"narration","text":"บนแผ่นหลังที่สวมเสื้อคาร์ดิแกนแขนยาวมีถุงทรงยาวสะพายอยู่ ความยาวน่าจะเกือบ 2 เมตร ซึ่งสูงเกินตัวเธอไปมาก ขนาดผมที่มีส่วนสูงตามมาตรฐานเด็กหนุ่ม ม.ปลาย ปี 1 ยังต้องเหลียวมองขึ้นไปเลย"},{"id":"b-5","type":"narration","text":"นักเรียนหญิงคนนั้นยืนนิ่งสนิท แม้จะสะพายสัมภาระที่ดูหนักอึ้งไว้บนหลังก็ตาม ชายกระโปรงที่สั้นนิดหน่อยไม่มีแม้แต่รอยพริ้วไหว เรียวขาทั้งสองข้างที่ห่อหุ้มด้วยถุงน่องสีดำก็หยุดนิ่งสงบ สิ่งเดียวที่ขยับคือปอยผมเล็กๆ ที่หลุดร่วงมาจากเรือนผมสีดำซึ่งรวบเป็นมวยอยู่หลังศีรษะ ปลิวไหวไปตามลมฤดูใบไม้ร่วงเบาๆ"},{"id":"b-6","type":"narration","text":"นักเรียนหญิงสองคนที่เดินอยู่ใกล้ๆ มองเธอแล้วพากันกระซิบกระซาบอย่างตื่นเต้น"},{"id":"b-7","type":"dialogue","speakerId":"girls_whisper","speakerName":"นักเรียนหญิง A","text":"“นี่ๆ นั่นใช่รุ่นพี่วาตานูกิหรือเปล่า?”"},{"id":"b-8","type":"dialogue","speakerId":"girls_whisper","speakerName":"นักเรียนหญิง B","text":"“เรื่องจริงเหรอเนี่ยที่สะพายคันธนูมาโรงเรียนตอนเช้า...!”"},{"id":"b-9","type":"dialogue","speakerId":"girls_whisper","speakerName":"นักเรียนหญิง A","text":"“เห็นว่าเป็นส่วนหนึ่งของการฝึกน่ะ ได้ยินเพื่อนชมรมยิงธนูซุบซิบมา”"},{"id":"b-10","type":"narration","text":"คงจะรู้ตัวว่ากำลังถูกพูดถึง รุ่นพี่วาตานูกิคนนั้นจึงหันกลับมาส่งรอยยิ้มและพยักหน้าให้อย่างสุภาพ จากนั้นก็หันกลับไปข้างหน้าตามเดิมอย่างเป็นธรรมชาติ"},{"id":"b-11","type":"narration","text":"แค่แวบเดียวที่ได้เห็นใบหน้าด้านข้างอันงดงามก็รู้ได้ทันที ของจริงชัดๆ รอยยิ้มสดใสเข้ากับท้องฟ้าฤดูใบไม้ร่วง ปราศจากความรำคาญใจที่ถูกซุบซิบโดยสิ้นเชิง"},{"id":"b-12","type":"narration","text":"และด้วยเสน่ห์อันสมบูรณ์แบบของรุ่นพี่วาตานูกิ ทำเอานักเรียนหญิงแถวนั้นพากันกรี้ดกร๊าดเสียงหลง จนนึกว่าดาราละครเวทีทาการาซุกะซะอีก โรงเรียนเรามีรุ่นพี่ชมรมยิงธนูที่มีออร่าเปรี้ยงปร้างขนาดนี้อยู่ด้วยแฮะ"},{"id":"b-13","type":"narration","text":"พอสัญญาณไฟเปลี่ยนสี ผมก็มองรุ่นพี่วาตานูกิเดินก้าวฉับๆ ไปพลาง แล้วค่อยๆ เดินเอื่อยๆ มุ่งหน้าไปโรงเรียนตามหลังเธอไป เอาเถอะ คงไม่มีอะไรต้องมาเกี่ยวข้องกันในอนาคตอยู่แล้ว... เพราะทางนี้เป็นพวกชมรมกลับบ้านที่ไม่มีพรสวรรค์ด้านกีฬาเลยสักนิด ที่สำคัญ ตอนนี้แค่รักษาความสัมพันธ์กับเพื่อนร่วมชั้นให้รอดไปวันๆ ก็เต็มกลืนแล้ว"},{"id":"b-14","type":"dialogue","speakerId":"toya","speakerName":"โทยะ","text":"“...ง่วงชะมัด”"},{"id":"b-15","type":"narration","text":"รู้สึกได้เลยว่าความเครียดสะสมเพราะอดนอนติดต่อกันหลายวัน สงสัยใกล้ถึงเวลาที่ต้องจัด—คอร์สผ่อนคลายสุดพิเศษที่ผมคิดค้นขึ้นมาเองแล้วล่ะมั้ง"},{"id":"b-16","type":"dialogue","speakerId":"toya","speakerName":"โทยะ","text":"“ฮ้าว...”"},{"id":"b-17","type":"narration","text":"ผมคิดอะไรไปเรื่อยเปื่อยพลางอ้าปากหาวออกมาตรงๆ ตามความง่วง ต่างจากรุ่นพี่คนสวยคนนั้น ตรงที่ผมไม่มีสายตาของใครคอยมองอยู่ เพราะงั้นจะแสดงอาการง่วงหมดสภาพยังไงก็ได้ ฟุฟุ พูดเองก็เริ่มรู้สึกเศร้าขึ้นมาเองซะแล้วสิ"},{"id":"b-18","type":"dialogue","speakerId":"classmate","speakerName":"เพื่อนร่วมชั้น","text":"“ไง อาเมโมโตะ! เมื่อคืนขอบใจที่มาไต่แรงก์ด้วยกันนะ! ดีใจที่เก็บแต้มขึ้นได้จนนอนไม่หลับเลยว่ะ!”"},{"id":"b-19","type":"narration","text":"แม้แต่คนไร้ตัวตนอย่างผม ก็ยังมีเพื่อนร่วมชั้นเข้ามาทักทายตั้งแต่เช้า ต่อให้จืดจางก็ไม่เป็นไร ถือว่าใช้ชีวิตได้ราบรื่นพอสมควรแล้ว ชีวิตประจำวันที่มีความเครียดน้อยเนี่ยแหละดีที่สุดแล้ว"},{"id":"b-20","type":"dialogue","speakerId":"toya","speakerName":"โทยะ","text":"“อรุณสวัสดิ์ ทางนี้ก็อดนอนเหมือนกันแหละ”"},{"id":"b-21","type":"narration","text":"ผมตอบกลับไปอย่างธรรมดาๆ พลางซึมซับชีวิตในโรงเรียนอันแสนสงบสุข"},{"id":"b-22","type":"scene_break","symbol":"◆"}]},{"id":"ch-02","number":2,"title":"อีเวนต์หายากกลางดึก ②","blocks":[{"id":"b2-1","type":"narration","text":"ผมลองขยี้ตาตัวเองอยู่สองสามครั้งเพราะสงสัยว่าตาฝาดไปหรือเปล่า"},{"id":"b2-2","type":"narration","text":"แต่ภาพของรุ่นพี่ที่ดูง่วงซึมก็ยังไม่หายไปไหน พูดถึงผี ผีก็มาเลยแฮะ?"},{"id":"b2-3","type":"narration","text":"รุ่นพี่วาตานูกิที่สวมเสื้อคลุมดูมีราคาหยิบกระป๋องสองสามใบขึ้นมา ก่อนจะหมุนตัวเดินกลับไปยังชั้นวางสินค้า"},{"id":"b2-4","type":"narration","text":"การเคลื่อนไหวอันว่องไวนั้น แม้จะเป็นแค่เรื่องธรรมดาในชีวิตประจำวัน แต่กลับมีความ 'เฉียบคม' บางอย่าง สดใสสง่างามไม่ต่างจากที่ผมเห็นเมื่อตอนเช้าเลย"},{"id":"b2-5","type":"narration","text":"เอ๋... รุ่นพี่วาตานูกิเป็นพวกออกมาซื้อเครื่องดื่มชูกำลังกองโตกลางดึกแบบนี้หรอกเหรอเนี่ย นี่มันความจริงอันน่าตกใจชัดๆ ภาพลักษณ์สุดเพอร์เฟกต์ที่ผมเพิ่งสร้างไว้ในหัวเมื่อตอนเช้า พังพินาศลงในพริบตาเดียว"},{"id":"b2-6","type":"narration","text":"เอาเถอะ ถึงความประทับใจที่มีต่อรุ่นพี่ที่ไม่เคยคุยกันมาก่อนจะเปลี่ยนไป มันก็ไม่ได้เกี่ยวกับผมอยู่ดีนั่นแหละ"},{"id":"b2-7","type":"narration","text":"รีบซื้อของให้เสร็จดีกว่า ผมรีบหยิบไอศกรีมของโปรดของเมอิมาสองถ้วย แล้วไปต่อแถวที่เคาน์เตอร์——เอ๊ะ รุ่นพี่ยังคิดเงินไม่เสร็จอีกเหรอ"},{"id":"b2-8","type":"narration","text":"เพราะเป็นร้านสะดวกซื้อที่ยังไม่มีเครื่องคิดเงินอัตโนมัติ ผมเลยมองเห็นขั้นตอนการชำระเงินได้โดยไม่ตั้งใจ"},{"id":"b2-9","type":"narration","text":"ยอดเงินที่แสดงอยู่เกือบจะถึง 7,000 เยน สำหรับเด็ก ม.ปลาย ถือเป็นเงินจำนวนมากทีเดียว"},{"id":"b2-10","type":"narration","text":"รุ่นพี่วาตานูกิหยิบธนบัตรสองสามใบออกจากคลิปหนีบเงินแล้ววางลงอย่างเรียบร้อย พนักงานชายเจาะหูพูดด้วยน้ำเสียงเย็นชา"},{"id":"b2-11","type":"dialogue","speakerId":"clerk","speakerName":"พนักงานร้านสะดวกซื้อ","text":"“จะสะสมแต้มไหมครับ”"},{"id":"b2-12","type":"dialogue","speakerId":"rino","speakerName":"วาตานูกิ ริโนะ","text":"“อ๊ะ ไม่ได้เป็นสมาชิกค่ะ... แต่เพราะซื้อของเยอะขนาดนี้ ถ้าสะสมได้ก็คงดีนะคะ”"},{"id":"b2-13","type":"dialogue","speakerId":"clerk","speakerName":"พนักงานร้านสะดวกซื้อ","text":"“งั้นช่วยดาวน์โหลดแอปพลิเคชันหน่อยนะครับ”"},{"id":"b2-14","type":"dialogue","speakerId":"rino","speakerName":"วาตานูกิ ริโนะ","text":"“ค่ะ...”"},{"id":"b2-15","type":"narration","text":"รุ่นพี่วาตานูกิที่ใช้น้ำเสียงเหนื่อยอ่อนควานหาของในกระเป๋าเสื้อคลุมสีดำกุกกัก แล้วก็หยุดนิ่งไป เอ๊ะ เกิดอะไรขึ้นน่ะ"},{"id":"b2-16","type":"dialogue","speakerId":"rino","speakerName":"วาตานูกิ ริโนะ","text":"“...เรื่องแต้มไม่รับแล้วดีกว่าค่ะ พอดีลืมสมาร์ตโฟนไว้...”"},{"id":"b2-17","type":"narration","text":"โถ น่าสงสารจัง... ความประทับใจแรกที่มีต่อรุ่นพี่วาตานูกิปลิวหายไปไหนหมดแล้วเนี่ย จะว่ายังไงดี ออร่าความน่าเวทนามันแผ่ออกมาจากตัวรุ่นพี่คนนี้เต็มเปี่ยมเลย"},{"id":"b2-18","type":"narration","text":"พอรุ่นพี่วาตานูกิยกถุงพลาสติกสองใบที่ใส่ของเรียบร้อยแล้วขึ้นมา เสียงกระป๋องเครื่องดื่มชูกำลังข้างในก็กระทบกันดังแกร๊กๆ"},{"id":"b2-19","type":"narration","text":"ดูหนักเอาเรื่องเลยแฮะ แต่ที่ยกไหวคงเพราะกำลังแขนของเด็กชมรมกีฬาละมั้ง สำหรับผมคงไม่ไหวหรอก เด็กแห้งแรงน้อยที่วิดพื้นได้ไม่ถึงห้าครั้งอย่างผม ขืนถือมีหวังข้อไหล่หลุดแน่"},{"id":"b2-20","type":"narration","text":"แต่ว่า ซื้อเครื่องดื่มชูกำลังเยอะขนาดนั้นไปทำไมกันนะ?"},{"id":"b2-21","type":"narration","text":"เมื่อก่อนผมก็เคยดื่มบ่อยๆ เวลาอยากฮึดตะลุยไต่แรงก์ในเกม รุ่นพี่วาตานูกิเองก็คงมี 'อะไรบางอย่าง' ที่ต้องใช้สมาธิสูงอยู่เหมือนกันละมั้ง"},{"id":"b2-22","type":"dialogue","speakerId":"clerk","speakerName":"พนักงานร้านสะดวกซื้อ","text":"“ขอบคุณที่อุดหนุนครับ”"}]},{"id":"ch-03","number":3,"title":"อีเวนต์หายากกลางดึก ③","blocks":[{"id":"b3-1","type":"narration","text":"พอเปิดประตูบ้านเข้ามา ก็เจออสูรยืนดักอยู่ตรงนั้นทันที"},{"id":"b3-2","type":"dialogue","speakerId":"mei","speakerName":"อาเมโมโตะ เมอิ","text":"“โท~ ยะ~?”"},{"id":"b3-3","type":"narration","text":"เสียงต่ำเชิงคาดคั้นลอดมาจากใต้หน้ากากอสูรของเมอิ (ของเล่นตลกๆ ที่เอาไว้ปิดบังหน้าสด)"},{"id":"b3-4","type":"dialogue","speakerId":"rino","speakerName":"วาตานูกิ ริโนะ","text":"“ฮี้...!”"},{"id":"b3-5","type":"narration","text":"พอเห็นหน้ากากที่มีเขี้ยวยื่นออกมา รุ่นพี่ก็ส่งเสียงร้องน่ารักแล้วยืนตัวเกร็งค้างไป"},{"id":"b3-6","type":"narration","text":"และคงเพราะปฏิกิริยาป้องกันตัว เธอเลยยื่นมือมาคว้าแขนผมไว้แน่น"},{"id":"b3-7","type":"dialogue","speakerId":"mei","speakerName":"อาเมโมโตะ เมอิ","text":"“ทำ~ไม แค่ใช้ออกไปซื้อของ ถึงได้พาคนดังประจำโรงเรียนอย่างคุณวาตานูกิเข้าบ้านมาได้ล่ะเนี่ย? ขืนพวกคนในโรงเรียนรู้เข้า มีหวังเป็นเรื่องใหญ่แน่ๆ เลยนะ!”"},{"id":"b3-8","type":"dialogue","speakerId":"toya","speakerName":"อาเมโมโตะ โทยะ","text":"“ก็บอกรายละเอียดให้ฟังทางโทรศัพท์เมื่อกี้แล้วไง ลางสังหรณ์มันบอกว่าพามาพักที่นี่ดีกว่า อีกอย่าง บ้านเราก็มีพี่สาวที่คุยกันรู้เรื่องอยู่ด้วย”"},{"id":"b3-9","type":"dialogue","speakerId":"mei","speakerName":"อาเมโมโตะ เมอิ","text":"“แบบว่า สมองมันเข้าใจอยู่หรอก แต่หัวใจมันตามไม่ทันน่ะสิ... แล้วก็ตัดสินใจฉับไวปานลมกรดเหมือนเดิมเลยนะ... ว่าแต่ เครื่องดื่มชูกำลังจำนวนน่ากลัวพวกนี้มันคืออะไรกันน่ะ?”"},{"id":"b3-10","type":"dialogue","speakerId":"toya","speakerName":"อาเมโมโตะ โทยะ","text":"“...ผมซื้อเอาไว้ดื่มเวลาต้องฮึดน่ะครับ”"},{"id":"b3-11","type":"dialogue","speakerId":"mei","speakerName":"อาเมโมโตะ เมอิ","text":"“เอ๋~! แล้วถ้าล้มพับไปอีกจะทำยังไงเล่า! ไม่อยากเห็นนอนซมเหมือนสมัยมัธยมต้นอีกแล้วนะ!?”"},{"id":"b3-12","type":"dialogue","speakerId":"toya","speakerName":"อาเมโมโตะ โทยะ","text":"“ไม่เป็นไรหรอกน่า คิดว่าตัวเองเข้าใจร่างกายดีที่สุดแล้วล่ะ ไม่ทำให้เมอิเป็นห่วงอีกแล้ว”"},{"id":"b3-13","type":"narration","text":"แต่พี่สาวผู้เป็นแกลสายจริงจังกลับพูดว่า “หนักใช่ไหมล่ะ เอามาข้างนึงสิ” แล้วยื่นมือมาช่วยอย่างระอาใจ ขอบคุณจริงๆ ครับ ขืนต้องถือต่ออีกนิด ไหล่ขวาผมหลุดแน่ๆ"},{"id":"b3-14","type":"narration","text":"ถึงจะต้องโกหกด้วยความรู้สึกผิด แต่ก็น่าจะรอดตัวไปได้โดยเรื่องไม่แตกสินะ ว่านี่เป็นของที่รุ่นพี่วาตานูกิซื้อมา"},{"id":"b3-15","type":"narration","text":"ทำแบบนี้จะดีจริงๆ เหรอครับ—พอผมหันไปมองผู้ร่วมกุมความลับ เจ้าตัวก็ยังคงหน้าซีด นั่งย่อย่อหมดแรงอยู่อย่างนั้น"},{"id":"b3-16","type":"dialogue","speakerId":"rino","speakerName":"วาตานูกิ ริโนะ","text":"“อะ อาเมโมโตะคุง... ทำไมเมอิซังถึงใส่หน้ากากอสูรล่ะคะ... ไม่นึกว่าจะโผล่มาแบบนี้ เลยตกใจไปหน่อยน่ะ...”"},{"id":"b3-17","type":"dialogue","speakerId":"toya","speakerName":"อาเมโมโตะ โทยะ","text":"“อ๊ะ นั่นสินะ เมอิ ถอดหน้ากากนั่นออกแล้วช่วยอธิบายเรื่องราวหน่อยสิ รุ่นพี่กลัวหมดแล้ว”"},{"id":"b3-18","type":"dialogue","speakerId":"mei","speakerName":"อาเมโมโตะ เมอิ","text":"“ไม่เอาๆ ไม่ยอมหรอก ถ้าต้องให้คนอื่นนอกจากโทยะเห็นหน้าสด ขอสวมหน้ากากอสูรใช้ชีวิตต่อไปดีกว่า”"},{"id":"b3-19","type":"narration","text":"อย่ามาละทิ้งความเป็นมนุษย์ด้วยเหตุผลแบบนั้นสิ แล้วที่ร้องไห้หนักมากตอนดู ‘ดาบพิฆาตอสูร’ วันก่อนมันคืออะไรกัน"},{"id":"b3-20","type":"narration","text":"ถึงไม่แต่งหน้า ผมว่าหน้าตาก็น่ารักออกนะ อันนี้ไม่ได้เข้าข้างเพราะเป็นคนกันเองหรอก ‘การประเมินตัวเองของเด็กสาววัยรุ่นมันเข้าใจยากนะเจ้าหนู’ คุณเมโลริลเองก็เคยพูดไว้แบบนี้นี่นา"},{"id":"b3-21","type":"narration","text":"แต่ตอนนี้ต้องต้อนรับแขกก่อน"},{"id":"b3-22","type":"dialogue","speakerId":"toya","speakerName":"อาเมโมโตะ โทยะ","text":"“ขอโทษด้วยนะครับ หน้ากากอสูรคงน่ากลัวแย่... เมอิ ไปเปลี่ยนเป็นหน้ากากที่ดูน่ารักกว่านี้หน่อยสิ อย่าทำให้รุ่นพี่วาตานูกิตกใจไปมากกว่านี้เลย”"}]},{"id":"ch-04","number":4,"title":"อีเวนต์ทั่วไปในชีวิตประจำวัน","blocks":[]},{"id":"ch-05","number":5,"title":"การปรึกษาและการปรึกษา","blocks":[]},{"id":"ch-06","number":6,"title":"คำแนะนำสัญญาชั่วคราว","blocks":[]},{"id":"ch-07","number":7,"title":"เจริญรอยตามตารางเวลา ①","blocks":[]},{"id":"ch-08","number":8,"title":"เจริญรอยตามตารางเวลา ②","blocks":[]}],"characters":[{"id":"rino","name":"วาตานูกิ ริโนะ","role":"ประธานชมรมยิงธนูสาวสวยรุ่นพี่","color":"#b84a5f","avatar":"/web-v2/assets/novels/kyudo-senpai/characters/char_rino.jpg"},{"id":"toya","name":"อาเมโมโตะ โทยะ","role":"ตัวเอก / ม.ปลาย ปี 1 ชมรมกลับบ้าน","color":"#42617a","avatar":"/web-v2/assets/novels/kyudo-senpai/characters/char_toya.png"},{"id":"mei","name":"อาเมโมโตะ เมอิ","role":"พี่สาวของโทยะ / ม.ปลาย ปี 2","color":"#bf7c32","avatar":"/web-v2/assets/novels/kyudo-senpai/characters/char_mei.png"},{"id":"classmate","name":"เพื่อนร่วมชั้น","role":"เพื่อนร่วมชั้น ม.ปลาย ปี 1","color":"#50785c","avatar":null},{"id":"girls_whisper","name":"นักเรียนหญิง","role":"นักเรียนที่เดินผ่าน","color":"#7c658a","avatar":null},{"id":"clerk","name":"พนักงานร้านสะดวกซื้อ","role":"พนักงานกะดึก","color":"#6e6a64","avatar":null}],"illustrations":[{"id":"illust_01","title":"ภาพสีเปิดเล่ม — วาตานูกิ ริโนะ","src":"/web-v2/assets/novels/kyudo-senpai/gallery/illust_01.webp"},{"id":"illust_02","title":"ภาพประกอบ 2 — สมาชิกชมรมยิงธนู","src":"/web-v2/assets/novels/kyudo-senpai/gallery/illust_02.webp"},{"id":"illust_03","title":"ภาพประกอบ 3 — วันสบายๆ หลังเลิกเรียน","src":"/web-v2/assets/novels/kyudo-senpai/gallery/illust_03.webp"},{"id":"illust_04","title":"ภาพประกอบ 4 — สองพี่น้องตระกูลวาตานูกิ","src":"/web-v2/assets/novels/kyudo-senpai/gallery/illust_04.webp"}]},{"id":"black-cat-hangout","title":"(WN) พอเก็บแมวดำมาเลี้ยง บ้านผมก็กลายเป็นแหล่งรวมตัวของสองสาวสวยไปซะแล้ว","originalTitle":"黒猫を拾ったら俺んちが二大美少女の溜まり場になった。","author":"มานะชิโระ คานาตะ (Manashiro Kanata)","artist":"อุนะซะกะ (Unasaka)","synopsis":"เมื่อ 6 ปีก่อน ผู้ชายแห่งโชคชะตาที่ไม่รู้จักแม้กระทั่งชื่อผู้เคยช่วยฉันไว้ คือคนที่เป็นรักแรกของเพื่อนสนิทที่สุดของฉัน... ฤดูใบไม้ผลินี้ ในโรงเรียนมัธยมปลายฮาคุเรียวไดที่นากาโนะ ทาคุมิ เพิ่งเข้าเรียน มีสองสาวสวยระดับท็อปของชั้นปี 1 ที่โดดเด่นสะดุดตาตั้งแต่เปิดเทอม นั่นคืออามาโนะ ฮินะ สาวสวยสายแกลผมบ๊อบนุ่มฟู กับโคคาเงะ มิซึกิ สาวสวยสายเรียบร้อยผมยาวดำ พวกเธอคือสาวสวยผู้เจิดจรัสที่ดูคนละโลกกับเด็กหนุ่มตัวประกอบอย่างเขา ทว่าการที่เขาได้ช่วยลูกแมวดำที่ถูกทิ้งไว้ระหว่างทางกลับบ้าน กลับทำให้เขาได้สนิทกับพวกเธอ และกลายเป็นจุดเริ่มต้นของเรื่องราวความรักอันอบอุ่นชวนใจฟู","tags":["Harem","Romance","School Life","Slice of Life","Wholesome & Fluffy"],"totalOriginalChapters":88,"cover":"/web-v2/assets/novels/black-cat-hangout/cover.jpg","banner":"/web-v2/assets/novels/black-cat-hangout/banner.jpg","chapters":[{"id":"ch-00","number":0,"title":"รูปประกอบ","blocks":[]},{"id":"ch-01","number":1,"title":"อามาโนะ ฮินะ กับ โคคาเงะ มิซึกิ","blocks":[{"id":"b-1","type":"narration","text":"ในฤดูใบไม้ผลินี้ ที่โรงเรียนมัธยมปลายฮาคุเรียวไดซึ่งผม—นากาโนะ ทาคุมิ เพิ่งเข้าเรียน มีสาวสวยโดดเด่นคู่หนึ่งที่ถูกขนานนามว่าเป็นสองสาวสวยระดับท็อปของชั้นปี 1 ตั้งแต่เพิ่งเปิดเทอม"},{"id":"b-2","type":"narration","text":"อามาโนะ ฮินะ กับ โคคาเงะ มิซึกิ"},{"id":"b-3","type":"narration","text":"ทั้งสองคนเป็นเพื่อนร่วมชั้นของผม"},{"id":"b-4","type":"dialogue","speakerId":"hina","speakerName":"อามาโนะ ฮินะ","text":"“เอ๊ะ จริงเหรอ? อะไรกันเนี่ย สุดยอดไปเลย!”"},{"id":"b-5","type":"narration","text":"ช่วงเวลาว่างยามเช้าระหว่างรอคาบโฮมรูมเริ่มต้น"},{"id":"b-6","type":"narration","text":"คนที่ส่งเสียงร่าเริงโดดเด่นออกมาท่ามกลางกลุ่มสาวโดดเด่นไม่กี่คนนั้นคือคุณอามาโนะ"},{"id":"b-7","type":"narration","text":"เธอเป็นสาวสวยสายแกลที่มีนิสัยสดใสและร่าเริง"},{"id":"b-8","type":"narration","text":"ผมสีน้ำตาลผ่านการกัดสีดัดลอนนุ่มฟูยาวประไหล่ (เคยได้ยินเธอบอกว่าเป็นทรงบ๊อบนุ่มฟู) มัดเป็นไซด์โพนีเล็กๆ ข้างเดียวแบบไม่สมมาตร ดูชิคและน่ารักดี"},{"id":"b-9","type":"narration","text":"เสื้อนักเรียนของเธอใส่แบบหลวมๆ สบายๆ ตอนนี้ก็ยังปลดกระดุมเสื้อเบลเซอร์ด้านหน้าทั้งหมด แถมกระดุมเสื้อเชิ้ตก็ปลดออกถึงสองเม็ด"},{"id":"b-10","type":"narration","text":"ริบบิ้นตรงหน้าอกก็ผูกหลวมๆ แต่น่าแปลกที่ไม่รู้สึกว่าดูไม่เป็นระเบียบเลยสักนิด"},{"id":"b-11","type":"narration","text":"ผมคิดว่ากระโปรงของเธอน่าจะสั้นที่สุดในชั้นปีแล้ว"},{"id":"b-12","type":"narration","text":"พวกผู้ชายที่เผลอมองตามทุกครั้งที่กระโปรงพลิ้วไหวตรงทางเดินหรือบันไดคงไม่ได้มีแค่ผมคนเดียวแน่ๆ"},{"id":"b-13","type":"narration","text":"วันที่อากาศหนาวเย็นแบบวันนี้ แต่งตัวแบบนั้นจะไม่หนาวเหรอ?"},{"id":"b-14","type":"narration","text":"ตั้งใจแต่งแฟชั่นแบบนั้นแท้ๆ แต่ผมดันไปเป็นห่วงเรื่องไม่เป็นเรื่องซะได้"},{"id":"b-15","type":"narration","text":"(ถึงจะเป็นสองสาวสวยระดับท็อปปี 1 แต่โดนคนอย่างผมมาเป็นห่วงคงรู้สึกยุ่งไม่เข้าเรื่องแหละ)"},{"id":"b-16","type":"narration","text":"ต่างจากคุณอามาโนะโดยสิ้นเชิง คุณโคคาเงะผู้เป็นอีกหนึ่งสาวสวยระดับท็อปของชั้นปี 1 คือสาวงามสายเรียบร้อย โดดเด่นด้วยผมยาวสีดำคลุมถึงกลางหลัง"},{"id":"b-17","type":"narration","text":"ดูเหมือนเธอจะไม่ค่อยถนัดกับพวกผู้ชายสักเท่าไหร่ พอมีผู้ชายเข้ามาร่วมวงสนทนาด้วยทีไร จำนวนคำพูดของเธอจะลดลงอย่างเห็นได้ชัด"},{"id":"b-18","type":"narration","text":"กระดุมเสื้อเชิ้ตติดเรียบร้อยจนถึงเม็ดบนสุด สวมเสื้อกั๊กสีน้ำเงินทับอีกชั้นเพื่อป้องกันความหนาวอย่างสมบูรณ์แบบ"},{"id":"b-19","type":"narration","text":"ริบบิ้นผูกแน่นสนิทตรงคอเสื้อ กระดุมเสื้อเบลเซอร์ก็กลัดครบทุกเม็ด"},{"id":"b-20","type":"narration","text":"แต่สิ่งที่ซ่อนอยู่ใต้เสื้อผ้านั้น คือหน้าอกหน้าใจอันอวบอิ่มที่เกินค่าเฉลี่ยของคนวัยเดียวกันไปไกล ซึ่งเรื่องนี้กลายเป็นข่าวลือในหมู่พวกผู้ชายไปแล้ว"},{"id":"b-21","type":"narration","text":"ผมไม่ได้เป็นคนพูดหรอกนะ แต่ยังไงมันก็เข้าหูอยู่ดี"},{"id":"b-22","type":"narration","text":"(เอ่อ... แบบว่านะ? ถ้าจะบอกว่าผมไม่ได้สนใจเลยสักนิด ก็คงเป็นคำโกหกล่ะนะ...)"}]},{"id":"ch-02","number":2,"title":"ผม ลูกแมว และคุณโคคาเงะ","blocks":[{"id":"b-1","type":"narration","text":"วันนั้น หลังจากเลิกเรียน ผมที่เพิ่งเข้าเรียนมัธยมปลายได้ไม่นานได้แวะไปเยี่ยมคุณย่าที่บ้านพักคนชรา"},{"id":"b-2","type":"narration","text":"และนี่คือช่วงระหว่างทางกลับบ้านในตอนนั้น"},{"id":"b-3","type":"dialogue","speakerId":"takumi","speakerName":"นากาโนะ ทาคุมิ","text":"“พยากรณ์อากาศบอกว่าฝนตกพรำๆ แท้ๆ ตกลงมาหนักเอาเรื่องเลยแฮะ อือ หนาวชะมัด รีบกลับบ้านไปเปิดสตรีมของท่านยามิฟัง แล้วเล่นสตรีทไฟเตอร์ 6 ดีกว่า”"},{"id":"b-4","type":"narration","text":"ผมกางร่มสีเขียวคันโปรด พลางรีบก้าวเท้ากลับบ้านท่ามกลางสายฝนอันหนาวเย็นในฤดูใบไม้ผลินั้น"},{"id":"b-5","type":"narration","text":"เหมียว... เหมียว..."},{"id":"b-6","type":"narration","text":"มีเสียงร้องแผ่วเบาแทรกผ่านเสียงฝนออกมาจากทางสวนสาธารณะที่ผมกำลังเดินผ่าน"},{"id":"b-7","type":"dialogue","speakerId":"takumi","speakerName":"นากาโนะ ทาคุมิ","text":"“เสียงจากสวนสาธารณะตรงนั้น... งั้นเหรอ? ไม่ได้หูฝาดไปเองใช่ไหมเนี่ย...”"},{"id":"b-8","type":"narration","text":"ด้วยความรู้สึกติดใจนิดหน่อย ผมเลยหยุดเดินแล้วลองเงี่ยหูฟังดู"},{"id":"b-9","type":"narration","text":"จากนั้น"},{"id":"b-10","type":"narration","text":"เหมียว... เหมียว..."},{"id":"b-11","type":"narration","text":"ถึงจะเกือบถูกเสียงฝนกลบหายไป แต่ก็มีเสียงร้องแผ่วเบาดังออกมาจริงๆ"},{"id":"b-12","type":"dialogue","speakerId":"takumi","speakerName":"นากาโนะ ทาคุมิ","text":"“นี่มัน... เสียงร้องของลูกแมวใช่ไหมเนี่ย?”"},{"id":"b-13","type":"narration","text":"ด้วยความห่วงผสมกับความอยากรู้อยากเห็น ผมจึงเดินตรงไปตามทิศทางของเสียงร้องนั้น"},{"id":"b-14","type":"narration","text":"พอเดินผ่านแผงกั้นตรงทางเข้าสวนสาธารณะ (เขาเรียกว่าอะไรแล้วนะ?) เข้าไปด้านใน แล้วตรงไปยังใต้ซุ้มต้นวิสทีเรียต้นใหญ่"},{"id":"b-15","type":"dialogue","speakerId":"takumi","speakerName":"นากาโนะ ทาคุมิ","text":"“คิดไว้ไม่ผิดเลย แมวถูกทิ้งจริงๆ ด้วย”"},{"id":"b-16","type":"narration","text":"มีลูกแมวตัวหนึ่งอยู่ในกล่องกระดาษที่มีผ้าขนหนูรองเอาไว้"},{"id":"b-17","type":"narration","text":"มันเป็นลูกแมวที่มีขนสีดำสนิทไปทั้งตัว"},{"id":"b-18","type":"narration","text":"ไม่ใช่แมวเพิ่งเกิด แต่เป็นลูกแมวดำที่ดูโตขึ้นมานิดหน่อย แต่ยังเล็กเกินกว่าจะเรียกว่าแมวโตเต็มวัย"},{"id":"b-19","type":"narration","text":"เหมียว... เหมียว..."},{"id":"b-20","type":"narration","text":"เจ้าลูกแมวดำตัวน้อยส่งเสียงร้องสุดกำลัง พลางช้อนดวงตาสีเขียวใสแจ๋วเงยหน้าขึ้นมองผม"},{"id":"b-21","type":"narration","text":"สายตาอันใสซื่อบริสุทธิ์ของมันสบเข้ากับดวงตาของผมพอดีเป๊ะ"},{"id":"b-22","type":"dialogue","speakerId":"takumi","speakerName":"นากาโนะ ทาคุมิ","text":"“อึก... อย่ามองกันด้วยสายตาแบบนั้นสิ...”"}]},{"id":"ch-03","number":3,"title":"คุณโคคาเงะที่ป้อนอาหารลูกแมว กับตัวผมที่คอยเฝ้ามอง","blocks":[{"id":"b-1","type":"dialogue","speakerId":"takumi","speakerName":"นากาโนะ ทาคุมิ","text":"“ถ้าไม่รังเกียจ ให้ผมถือร่มให้ไหม?”"},{"id":"b-2","type":"dialogue","speakerId":"mizuki","speakerName":"โคคาเงะ มิซึกิ","text":"“เอ๊ะ?”"},{"id":"b-3","type":"dialogue","speakerId":"takumi","speakerName":"นากาโนะ ทาคุมิ","text":"“ถือมือเดียวคงป้อนอาหารลำบากใช่ไหมล่ะ? แน่นอนว่าถ้าไม่ได้เกะกะอะไรนะ”"},{"id":"b-4","type":"narration","text":"ไม่ว่าจะตัดซองหรือป้อนให้ลูกแมวกิน ถ้าต้องถือร่มไปด้วยคงลำบากน่าดู ผมคิดแบบนั้น"},{"id":"b-5","type":"narration","text":"เพราะงั้นนี่เลยเป็นข้อเสนอตามปกติธรรมดา ไม่ได้ฉวยโอกาสนี้รุกเข้าหาเพื่อตีสนิทกับคุณโคคาเงะอะไรแบบนั้นสักหน่อย"},{"id":"b-6","type":"narration","text":"เรื่องนี้เป็นเรื่องจริงแท้แน่นอนเลยนะ!"},{"id":"b-7","type":"narration","text":"--แล้วทำไมผมต้องมานั่งแก้ตัวกับตัวเองในใจด้วยเนี่ย"},{"id":"b-8","type":"narration","text":"แต่ว่า ผมอาจจะพูดอะไรไม่เข้าเรื่องออกไปก็ได้นะ"},{"id":"b-9","type":"narration","text":"เห็นว่าคุณโคคาเงะไม่ค่อยถูกกับผู้ชายด้วย อาจจะโดนเข้าใจผิดว่าเอาลูกแมวมาเป็นข้ออ้างเพื่อขยับเข้ามาใกล้ชิดก็ได้"},{"id":"b-10","type":"narration","text":"ระหว่างที่ผมกำลังเกร็งจนหัวใจเต้นตึกตักอยู่นั้นเอง"},{"id":"b-11","type":"dialogue","speakerId":"mizuki","speakerName":"โคคาเงะ มิซึกิ","text":"“...ถ้างั้น ฝากด้วยจะได้ไหมคะ?”"},{"id":"b-12","type":"narration","text":"คุณโคคาเงะเว้นจังหวะคิดอยู่ครู่หนึ่ง ก่อนจะพูดออกมาพร้อมรอยยิ้มบางๆ อย่างเรียบร้อย"},{"id":"b-13","type":"dialogue","speakerId":"takumi","speakerName":"นากาโนะ ทาคุมิ","text":"“อ๊ะ อื้อ ไว้ใจได้เลย”"},{"id":"b-14","type":"narration","text":"ผมรับร่มของคุณโคคาเงะมาถือไว้ แล้วใช้ทักษะถือร่มสองมือพร้อมกัน"},{"id":"b-15","type":"narration","text":"ขณะที่เผลอมองคุณโคคาเงะที่ตั้งใจรวบกระโปรงหนีบไว้ระหว่างเข่าอย่างระมัดระวังเพื่อไม่ให้โดนพื้นเปเปียกๆ ผมก็รีบกางร่มของคุณโคคาเงะคลุมเหนือร่างของเธอที่ย่อตัวลงไป เพื่อไม่ให้เธอต้องเปียกฝน"},{"id":"b-16","type":"dialogue","speakerId":"takumi","speakerName":"นากาโนะ ทาคุมิ","text":"“เอาล่ะ เชิญเลย”"},{"id":"b-17","type":"narration","text":"คุณโคคาเงะที่มือทั้งสองข้างเป็นอิสระแล้ว ได้โอกาสยื่นขนมแมวเลียแบบซองเข้าไปใกล้ปากของลูกแมว"},{"id":"b-18","type":"narration","text":"เหมียว!"},{"id":"b-19","type":"narration","text":"คงจะหิวมากจริงๆ ลูกแมวส่งเสียงร้องสดใสขึ้นมาผิดกับเมื่อกี้ลิบลับ แล้วเริ่มกินอย่างเอร็ดอร่อยโดยไม่ระแวงเลยสักนิด"},{"id":"b-20","type":"dialogue","speakerId":"mizuki","speakerName":"โคคาเงะ มิซึกิ","text":"“ว้าว กินเก่งจังเลยค่ะ”"},{"id":"b-21","type":"dialogue","speakerId":"takumi","speakerName":"นากาโนะ ทาคุมิ","text":"“คงจะหิวมากเลยสินะ”"},{"id":"b-22","type":"narration","text":"งับๆๆๆ"}]},{"id":"ch-04","number":4,"title":"คุณโคคาเงะผู้ขี้วิตก","blocks":[]},{"id":"ch-05","number":5,"title":"“ถ้าอย่างนั้น ตอนนี้ขอตามไปบ้านคุณนากาโนะด้วยได้ไหมคะ?”","blocks":[]},{"id":"ch-06","number":6,"title":"ผม คุณโคคาเงะ และการกางร่มคันเดียวกัน","blocks":[]},{"id":"ch-07","number":7,"title":"“เดี๋ยวสิ! รอแป๊บหนึ่งเลยนะ!”","blocks":[]},{"id":"ch-08","number":8,"title":"คุณโคคาเงะกับคุณอามาโนะที่หยอกล้อกัน","blocks":[]}],"characters":[{"id":"takumi","name":"นากาโนะ ทาคุมิ","role":"ตัวเอก / ม.ปลาย ปี 1 โรงเรียนฮาคุเรียวได","color":"#3f6f8f","avatar":null},{"id":"hina","name":"อามาโนะ ฮินะ","role":"สาวสวยระดับท็อปปี 1 สายแกล","color":"#e2766a","avatar":"/web-v2/assets/novels/black-cat-hangout/characters/char_blackcat_hina.jpg"},{"id":"mizuki","name":"โคคาเงะ มิซึกิ","role":"สาวสวยระดับท็อปปี 1 สายเรียบร้อย","color":"#7286c4","avatar":"/web-v2/assets/novels/black-cat-hangout/characters/char_blackcat_mizuki.jpg"},{"id":"kuro","name":"คุโรโตะ","role":"ลูกแมวดำ","color":"#5c5560","avatar":"/web-v2/assets/novels/black-cat-hangout/characters/char_blackcat_kuro.jpg"},{"id":"yumi","name":"นิตตะ ยูมิ","role":"เพื่อนร่วมชั้น ม.ปลาย ปี 1 (กลุ่มสาวสวย)","color":"#e08244","avatar":null},{"id":"classmate","name":"เพื่อนร่วมชั้น","role":"เพื่อนร่วมชั้น ม.ปลาย ปี 1","color":"#50785c","avatar":null}],"illustrations":[{"id":"illust_01","title":"ภาพสีเปิดเล่ม — ฮินะกับมิซึกิในชุดนักเรียน","src":"/web-v2/assets/novels/black-cat-hangout/gallery/illust_01.jpg"},{"id":"illust_02","title":"ภาพประกอบ 2 — มิซึกิในชุดแมวดำ","src":"/web-v2/assets/novels/black-cat-hangout/gallery/illust_02.jpg"},{"id":"illust_03","title":"ภาพประกอบ 3 — ฮินะกับมิซึกิในชุดผ้ากันเปื้อน","src":"/web-v2/assets/novels/black-cat-hangout/gallery/illust_03.jpg"},{"id":"illust_04","title":"ภาพประกอบ 4 — ฮินะในชุดแมวดำ","src":"/web-v2/assets/novels/black-cat-hangout/gallery/illust_04.jpg"}]},{"id":"boyish-friend","title":"[18+] เรื่องราวของการพรากเพื่อนสนิทสาวที่น่ารักอันดับสองในห้อง มาเป็นของตัวเองด้วยทริปทัศนศึกษาสองคืนสามวัน","originalTitle":"クラスで２番目に可愛いボーイッシュ幼馴染の完全攻略神託チャート","author":"月見ハク (Tsukimi Haku)","artist":"あかつき聖 (Akatsuki Hijiri)","synopsis":"เด็กหนุ่ม ม.ปลาย ธรรมดาผู้แอบหลงรัก 'มินะโทริ อายะ' เพื่อนสมัยเด็กผมสั้นสไตล์บอยอิชที่น่ารักและร่าเริงที่สุดคนหนึ่งในห้อง แต่กลับไม่เคยกล้าก้าวข้ามสถานะเพื่อน จนกระทั่งในทริปทัศนศึกษา 2 คืน 3 วัน เขาได้รับพลังและการชี้นำให้เริ่มต้นแผนการรุกคืบ สัมผัส และผูกมัดทั้งหัวใจและร่างกายของเธอ จนก้าวข้ามเส้นคำว่าเพื่อนสู่ความสัมพันธ์อันลึกซึ้งที่ไม่อาจหวนกลับ","tags":["Mature 18+","Romance","Drama","School Life","Childhood Friend","Boyish Heroine"],"totalOriginalChapters":99,"cover":"/web-v2/assets/novels/boyish-friend/cover.jpg","banner":"/web-v2/assets/novels/boyish-friend/banner.jpg","chapters":[{"id":"ch-01","number":1,"title":"บททัศนศึกษา - ได้พลังที่จะแย่งชิงเพื่อนสมัยเด็กมาครอบครอง (วันแรก ศุกร์ กลางวัน)","blocks":[{"id":"b-1","type":"narration","text":"ฉันเหม่อมองออกไปนอกหน้าต่างรถทัศนศึกษา"},{"id":"b-2","type":"narration","text":"อากาศร้อนอบอ้าว จนทิวทัศน์บ้านเรือนเก่าแก่เบื้องนอกดูราวกับกำลังระริกไหวไปกับความร้อน"},{"id":"b-3","type":"narration","text":"วันนี้คือวันแรกของทัศนศึกษาของโรงเรียน"},{"id":"b-4","type":"narration","text":"เพื่อนร่วมชั้นเรียนต่างส่งเสียงเจี๊ยวจ๊าวกันอย่างไม่สนใจคำอธิบายของมัคคุเทศก์บนรถเลยสักนิด"},{"id":"b-5","type":"narration","text":"คงกำลังพูดคุยเรื่องความรักกันอย่างสนุกสนานตามเคยล่ะมั้ง"},{"id":"b-6","type":"narration","text":"เป็นเรื่องที่ไม่เกี่ยวข้องกับฉันที่ไม่มีดวงเรื่องความรักเลยสักนิด"},{"id":"b-7","type":"narration","text":"ทันใดนั้น มีคนมานั่งลงบนที่นั่งว่างข้างๆ"},{"id":"b-8","type":"dialogue","speakerId":"aya","speakerName":"มินะโทริ อายะ","text":"“ไงเจ้าคนเหม่อ มองอะไรอยู่เหรอ?”"},{"id":"b-9","type":"dialogue","speakerId":"protagonist","speakerName":"โบยัน (ตัวเอก)","text":"“อายะเหรอ... เอ่อ... ก็มองออกไปข้างนอกน่ะ”"},{"id":"b-10","type":"dialogue","speakerId":"aya","speakerName":"มินะโทริ อายะ","text":"“ข้างนอกเหรอ?”"},{"id":"b-11","type":"narration","text":"หัวสีน้ำตาลแบบซอยสั้นโผล่เข้ามาในสายตาของฉัน อายะโน้มตัวมาทางที่นั่งของฉันเพื่อมองออกไปนอกหน้าต่าง"},{"id":"b-12","type":"narration","text":"เสื้อแขนสั้นสีขาวของเธอช่างดูเจิดจ้า"},{"id":"b-13","type":"dialogue","speakerId":"aya","speakerName":"มินะโทริ อายะ","text":"“ก็ไม่มีอะไรนี่นา”"},{"id":"b-14","type":"narration","text":"อายะพูดพลางหันหน้ามาทางฉัน"},{"id":"b-15","type":"dialogue","speakerId":"aya","speakerName":"มินะโทริ อายะ","text":"“อึ่ก...”"},{"id":"b-16","type":"narration","text":"เสียงแปลกๆ หลุดออกมาจากปากฉัน เมื่อต้องเผชิญหน้ากับความน่ารักของอายะในระยะใกล้"},{"id":"b-17","type":"narration","text":"มินะโทริ อายะ"},{"id":"b-18","type":"narration","text":"เด็กผู้หญิงที่เรียนอยู่ห้องเดียวกับฉัน มีเอกลักษณ์คือผมสั้นสีน้ำตาล"},{"id":"b-19","type":"narration","text":"และเป็นเพื่อนสมัยเด็กของฉันตั้งแต่สมัยประถม"},{"id":"b-20","type":"narration","text":"อายะมีนิสัยร่าเริงและเปิดเผยตามรูปลักษณ์แบบเด็กผู้ชาย ทำให้เป็นที่นิยมในหมู่ทั้งชายและหญิง"},{"id":"b-21","type":"narration","text":"แถมใบหน้าก็ยังได้รูปอีกด้วย"},{"id":"b-22","type":"narration","text":"ปกติแล้วหน้าของเธอจะดูอ่อนกว่าวัย และวันนี้ก็ไม่ได้แต่งหน้า เลยอยู่ในระดับ “น่ารักแบบมีเสน่ห์” แต่ถ้าได้แต่งหน้าแล้วล่ะก็ เธอคงจะกลายเป็น “สาวงาม” ได้ในพริบตาเลย"}]},{"id":"ch-02","number":2,"title":"บททัศนศึกษา - เพื่อนสมัยเด็กถูกบังคับจูบจนแทบสำลัก (วันแรก ศุกร์ กลางคืน)","blocks":[{"id":"b-1","type":"narration","text":"ที่พักเป็นโรงแรมในเกียวโต"},{"id":"b-2","type":"narration","text":"ทุกคนทานอาหารเย็นและไปแช่น้ำร้อนในห้องอาบน้ำรวม"},{"id":"b-3","type":"narration","text":"ส่วนฉันกำลังอยู่ในห้องของเด็กผู้หญิง"},{"id":"b-4","type":"narration","text":"โรงแรมแบ่งเป็นห้องสำหรับสี่ถึงแปดคน มีทั้งแบบห้องสไตล์ญี่ปุ่นและสไตล์ตะวันตก"},{"id":"b-5","type":"narration","text":"กลุ่มของฉันได้ห้องสไตล์ตะวันตกสำหรับสี่คน"},{"id":"b-6","type":"narration","text":"พอฉันกลับมาที่ห้อง กลุ่มของฉันก็บอกว่าจะไป “ห้องเด็กผู้หญิง” ฉันเลยตามไปด้วย"},{"id":"b-7","type":"dialogue","speakerId":"classmate","speakerName":"เพื่อนร่วมชั้น","text":"“หา! โบยันก็จะไปด้วยเหรอ!?” พวกนั้นตกใจ"},{"id":"b-8","type":"narration","text":"พวกเราเดินไปตามทางเดินอย่างเงียบเชียบ เพื่อไม่ให้ถูกครูที่เดินตรวจตราเจอ"},{"id":"b-9","type":"dialogue","speakerId":"classmate","speakerName":"เพื่อนร่วมชั้น","text":"“เฮ้ย! โบยัน! ถ้าเดินไปอย่างนั้นเดี๋ยวครูก็เห็นหรอก!”"},{"id":"b-10","type":"narration","text":"พวกในกลุ่มกระซิบด้วยน้ำเสียงกระวนกระวาย"},{"id":"b-11","type":"dialogue","speakerId":"classmate","speakerName":"เพื่อนร่วมชั้น","text":"“ไม่หรอก ไม่เจอหรอก”"},{"id":"b-12","type":"narration","text":"ไม่รู้ทำไม แต่ฉันมั่นใจอย่างนั้น"},{"id":"b-13","type":"narration","text":"สถานที่นัดพบคือห้องแปดคนของเด็กผู้หญิง"},{"id":"b-14","type":"narration","text":"เป็นห้องแบบญี่ปุ่นที่ปูฟูกไว้แล้ว"},{"id":"b-15","type":"narration","text":"ดูเหมือนว่าจะมีเด็กผู้ชายจากกลุ่มอื่นด้วย ซึ่งมีโทกิตะอยู่ด้วย"},{"id":"b-16","type":"narration","text":"และแน่นอน ในบรรดาเด็กผู้หญิงก็มีอายะอยู่"},{"id":"b-17","type":"narration","text":"ทันทีที่เห็นฉัน อายะก็เบิกตากว้าง แต่ก็ยิ้มออกมาทันที"},{"id":"b-18","type":"narration","text":"คงจะรู้สึกดีที่เห็นฉันเริ่มเข้าหาเพศตรงข้ามบ้าง"},{"id":"b-19","type":"narration","text":"อายะอยู่ในชุดเสื้อฮู้ดแขนสั้นสีน้ำเงินกรมท่ากับกางเกงวอร์มผ้าไนลอนสีดำ"},{"id":"b-20","type":"narration","text":"เป็นชุดนอนที่ดูสบายๆ สไตล์เธอ"},{"id":"b-21","type":"narration","text":"แม้เสื้อฮู้ดจะตัวใหญ่หลวมๆ แต่ส่วนโค้งนูนของหน้าอกอวบอิ่มของอายะก็ยังดันเนื้อผ้าให้ยกขึ้นมา"},{"id":"b-22","type":"narration","text":"ฉันรู้ว่าเด็กผู้ชายคนอื่นต่างก็แอบมองหน้าอกอวบอิ่มนั้น"}]},{"id":"ch-03","number":3,"title":"บททัศนศึกษา - ผลักเพื่อนสมัยเด็กที่ต้องการเหตุผลลงกับเตียง (วันแรก ศุกร์ ดึก)","blocks":[{"id":"b-1","type":"narration","text":"ก๊อกๆ... มีเสียงเคาะประตูเบาๆ"},{"id":"b-2","type":"narration","text":"เมื่อเปิดออก อายะก็ยืนอยู่"},{"id":"b-3","type":"dialogue","speakerId":"protagonist","speakerName":"โบยัน (ตัวเอก)","text":"“ขอโทษนะที่ต้องให้แอบออกมา... เข้ามาสิ”"},{"id":"b-4","type":"dialogue","speakerId":"aya","speakerName":"มินะโทริ อายะ","text":"“...อืม”"},{"id":"b-5","type":"dialogue","speakerId":"protagonist","speakerName":"โบยัน (ตัวเอก)","text":"“ไม่เป็นไรนะ? เอ่อ... คนอื่นๆ น่ะ”"},{"id":"b-6","type":"dialogue","speakerId":"aya","speakerName":"มินะโทริ อายะ","text":"“อืม บอกว่าไปห้องยูคาริมาน่ะ เพราะงั้น... ถ้าไม่ไปห้องยูคาริต่อ คงจะดูแปลกๆ...”"},{"id":"b-7","type":"narration","text":"ยูคาริคือเพื่อนผู้หญิงคนหนึ่งของอายะ"},{"id":"b-8","type":"narration","text":"เธอพูดพร้อมกับกำโทรศัพท์แน่น เพื่อบอกเป็นนัยว่าอยู่ห้องนี้ได้ไม่นาน"},{"id":"b-9","type":"narration","text":"ก็แน่อยู่แล้วล่ะ"},{"id":"b-10","type":"narration","text":"ถึงแม้จะเป็นโบยัน แต่ก็เป็นคนที่บังคับจูบเธอเมื่อกี้ ยังไงก็ต้องระแวงอยู่แล้ว"},{"id":"b-11","type":"dialogue","speakerId":"protagonist","speakerName":"โบยัน (ตัวเอก)","text":"“เดี๋ยวเดียวก็เสร็จแล้ว นั่งตรงนั้นสิ”"},{"id":"b-12","type":"narration","text":"ฉันผายมือไปที่เตียง อายะก็นั่งลงอย่างว่าง่าย"},{"id":"b-13","type":"narration","text":"ฉันนั่งลงบนเตียงฝั่งตรงข้าม พอดีกับระยะที่ฉันเอื้อมมือไปถึงตัวอายะได้พอดี"},{"id":"b-14","type":"dialogue","speakerId":"aya","speakerName":"มินะโทริ อายะ","text":"“เมื่อกี้ขอโทษด้วยนะ คือว่า... ฉันควบคุมอารมณ์ตัวเองไม่ได้น่ะ ไม่ชอบเลยใช่ไหม?”"},{"id":"b-15","type":"dialogue","speakerId":"protagonist","speakerName":"โบยัน (ตัวเอก)","text":"“ไม่เชิงว่าไม่ชอบ... แต่ก็ตกใจน่ะ”"},{"id":"b-16","type":"dialogue","speakerId":"aya","speakerName":"มินะโทริ อายะ","text":"“อืม ขอโทษ...”"},{"id":"b-17","type":"narration","text":"ฉันจ้องมองอายะตรงๆ"},{"id":"b-18","type":"narration","text":"เมื่อเราสบตากันโดยไม่ทันตั้งตัว อายะก็หันสายตาหนีอย่างรู้สึกอึดอัด"},{"id":"b-19","type":"narration","text":"แต่เพราะฉันขอโทษอย่างตรงไปตรงมา เธอเลยดูผ่อนคลายลงกว่าเมื่อกี้"},{"id":"b-20","type":"narration","text":"โทรศัพท์ที่เธอกำไว้ที่อกก็วางอยู่บนตักแล้ว"},{"id":"b-21","type":"dialogue","speakerId":"aya","speakerName":"มินะโทริ อายะ","text":"“นี่โบยัน... ทำไมถึงทำเรื่องแบบนั้นลงไปล่ะ?”"},{"id":"b-22","type":"dialogue","speakerId":"protagonist","speakerName":"โบยัน (ตัวเอก)","text":"“ก็เพราะว่าฉัน...”"}]},{"id":"ch-04","number":4,"title":"บททัศนศึกษา - จู่โจมเพื่อนสมัยเด็กที่หวาดระแวง (วันที่สอง เสาร์ บ่าย)","blocks":[]},{"id":"ch-05","number":5,"title":"บททัศนศึกษา - ลากเพื่อนสมัยเด็กที่ไม่ยอมเรียกชื่อเข้าไปในห้องน้ำ (วันที่สอง เสาร์ เย็น)","blocks":[]},{"id":"ch-06","number":6,"title":"บททัศนศึกษา - ทรมานเพื่อนสมัยเด็กที่เร่าร้อน (วันที่สอง เสาร์ กลางคืน)","blocks":[]},{"id":"ch-07","number":7,"title":"บททัศนศึกษา - พาเพื่อนสมัยเด็กที่สับสนเข้าไปในห้องว่าง (วันที่สอง เสาร์ ดึก)","blocks":[]},{"id":"ch-08","number":8,"title":"บททัศนศึกษา - ทำเครื่องหมายความเป็นเจ้าของกับเพื่อนสมัยเด็กที่รักมาตลอด (คืนที่สอง เสาร์ ดึก)","blocks":[]}],"characters":[{"id":"protagonist","name":"โบยัน (ตัวเอก)","role":"ตัวเอก / เพื่อนสมัยเด็กของอายะ","color":"#3c6e85","avatar":"/web-v2/assets/novels/boyish-friend/characters/char_boyish_boyan.jpg"},{"id":"aya","name":"มินะโทริ อายะ","role":"เพื่อนสมัยเด็กสาวผมสั้น","color":"#d96b34","avatar":"/web-v2/assets/novels/boyish-friend/characters/char_boyish_aya.jpg"},{"id":"tokita","name":"โทกิตะ","role":"เพื่อนร่วมชั้น / แฟนของอายะ","color":"#6c5b7b","avatar":"/web-v2/assets/novels/boyish-friend/characters/char_boyish_tokita.jpg"},{"id":"classmate","name":"เพื่อนร่วมชั้น","role":"นักเรียนร่วมรุ่น","color":"#64748b","avatar":null},{"id":"guide","name":"มัคคุเทศก์","role":"ผู้นำทัศนศึกษา","color":"#16a34a","avatar":null}],"illustrations":[]},{"id":"makeine-too-many-losing-heroines","title":"รักครั้งนี้มีคนนกเยอะไปมั้ย !","originalTitle":"負けヒロインが多すぎる!","author":"อมาโมริ ทาคิบิ (Amamori Takibi / 雨森たきび)","artist":"อิมิงิมุรุ (Imigimuru / いみぎむる)","synopsis":"เรื่องราวของเหล่านางเอกที่เปล่งประกายหลังจากถูกปฏิเสธ! นุคุมิซึ คาสึฮิโกะ เด็กหนุ่มมัธยมปลายที่พอใจกับการกลมกลืนไปกับฝูงชน จนกระทั่งวันหนึ่งเขาได้พบกับยานามิ อันนะ เพื่อนร่วมชั้นที่ได้รับความนิยมแต่ถูกเพื่อนสมัยเด็กของเธอทิ้ง เขาจึงพยายามปลอบใจเธอ แต่เหตุการณ์นั้นกลับทำให้เขาต้องพัวพันกับเหล่าสาวน้อยที่เพิ่งพบกับความพ่ายแพ้ในความรักคนแล้วคนเล่า","tags":["Comedy","Romance","School Life","Slice of Life"],"totalOriginalChapters":182,"cover":"/web-v2/assets/novels/makeine-too-many-losing-heroines/cover.jpg","banner":"/web-v2/assets/novels/makeine-too-many-losing-heroines/banner.jpg","chapters":[],"characters":[{"id":"nukumizu","name":"นุคุมิซึ คาสึฮิโกะ","role":"ตัวเอก / ผู้เล่าเรื่อง","color":"#5b6b7a","avatar":null},{"id":"yanami","name":"ยานามิ อันนะ","role":"นางเอกสายนก / เพื่อนร่วมชั้น","color":"#2f6fb0","avatar":"/web-v2/assets/novels/makeine-too-many-losing-heroines/characters/char_makeine_yanami.jpg"},{"id":"komari","name":"โคมาริ ชิกะ","role":"รองประธานชมรมวรรณกรรม","color":"#b83a5a","avatar":"/web-v2/assets/novels/makeine-too-many-losing-heroines/characters/char_makeine_komari.jpg"},{"id":"yakishio","name":"ยากิชิโอะ เลม่อน","role":"นักวิ่งชมรมกรีฑา","color":"#c9a227","avatar":"/web-v2/assets/novels/makeine-too-many-losing-heroines/characters/char_makeine_yakishio.jpg"},{"id":"shiratama","name":"ชิราทามะ ริโกะ","role":"รุ่นน้องชมรมวรรณกรรม","color":"#9aa0ad","avatar":"/web-v2/assets/novels/makeine-too-many-losing-heroines/characters/char_makeine_shiratama.jpg"},{"id":"shikiya","name":"ชิกิยะ ยูเมโกะ","role":"เลขานุการสภานักเรียน","color":"#7a6aa8","avatar":"/web-v2/assets/novels/makeine-too-many-losing-heroines/characters/char_makeine_shikiya.jpg"}],"illustrations":[]}]};
